public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Arguments must not be null");
    }
    try {
        int size = 0;
        while (true) {
            LinkedBuffer nextBuffer = buffer.start();
            size = schema.writeTo(nextBuffer, message);
            if (nextBuffer.start == nextBuffer.offset) {
                // Buffer has not been used, we can reuse it
                buffer = nextBuffer;
                break;
            }
            // Check if there is more data to write
            if (nextBuffer.next == null) {
                break;
            }
            // Move to the next buffer
            buffer = nextBuffer.next;
        }
        byte[] sizeBuffer = new byte[Varint.computeRawVarint32Size(size)];
        Varint.writeRawVarint32(sizeBuffer, 0, size);
        out.write(sizeBuffer);
        LinkedBuffer lb = buffer;
        do {
            out.write(lb.buffer, lb.start, lb.offset - lb.start);
            lb = lb.next;
        } while (lb != null);
        return size + sizeBuffer.length;
    } catch (Exception e) {
        throw new IOException("Error writing message to OutputStream", e);
    } finally {
        buffer.clear();
    }
}

