static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        if (dayStep <= 0) {
            throw new IllegalArgumentException("dayStep must be greater than 0");
        }

        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket / 100) % 100);
        int day = (int) (timeBucket % 100);

        // Assuming the year and month are valid, we calculate the day of the year
        int[] daysInMonth = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)) {
            daysInMonth[1] = 29; // Leap year
        }

        if (month < 1 || month > 12 || day < 1 || day > daysInMonth[month - 1]) {
            throw new IllegalArgumentException("Invalid date in timeBucket");
        }

        int dayOfYear = 0;
        for (int i = 0; i < month - 1; i++) {
            dayOfYear += daysInMonth[i];
        }
        dayOfYear += day;

        // Calculate the new day of the year based on dayStep
        int newDayOfYear = ((dayOfYear - 1) / dayStep) * dayStep + 1;

        // Convert the new day of the year back to day, month, year
        int newMonth = 0;
        int newDay = newDayOfYear;
        for (newMonth = 0; newMonth < 12; newMonth++) {
            if (newDay <= daysInMonth[newMonth]) {
                break;
            }
            newDay -= daysInMonth[newMonth];
        }

        newMonth += 1; // Convert 0-based index to 1-based month

        return year * 10000L + newMonth * 100L + newDay;
    } catch (Exception e) {
        // Handle exceptions and return a default or error value
        e.printStackTrace();
        return -1;
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("Index and length must be non-negative and within the bounds of the string");
    }

    int size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            if (i + 1 < index + len) {
                char lowSurrogate = str.charAt(i + 1);
                if (Character.isLowSurrogate(lowSurrogate)) {
                    size += 4; // Two surrogate characters form a complete code point outside the Basic Multilingual Plane
                    i++; // Skip the low surrogate as it's already counted
                } else {
                    throw new IllegalArgumentException("High surrogate without corresponding low surrogate");
                }
            } else {
                throw new IllegalArgumentException("High surrogate at the end of the string");
            }
        } else {
            size += 3;
        }
    }
    return size;
}

