    }
    if (value == null) {
        throw new Exception("Cannot convert null to Character.");
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String strValue = (String) value;
        if (strValue.length() == 1) {
            return strValue.charAt(0);
        } else {
            throw new Exception("String must be of length 1 to convert to Character.");
        }
    }
    if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        if (intValue >= Character.MIN_VALUE && intValue <= Character.MAX_VALUE) {
            return (char) intValue;
        } else {
            throw new Exception("Number is out of range for Character.");
        }
    }
    throw new Exception("Conversion from " + value.getClass() + " to Character is not supported.");
}

