public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }

    StringBuilder sb = new StringBuilder();
    char[] chars = str.toCharArray();
    for (int i = 0; i < chars.length; i++) {
        char c = chars[i];
        if (c == '\\') {
            if (i + 1 >= chars.length) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            char nextChar = chars[++i];
            switch (nextChar) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case 'u':
                    if (i + 4 >= chars.length) {
                        throw new Exception("Invalid Unicode escape sequence");
                    }
                    String unicode = new String(chars, i + 1, 4);
                    sb.append((char) Integer.parseInt(unicode, 16));
                    i += 4;
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\" + nextChar);
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

