protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new SimpleGraphPath<>(graph, null, Collections.emptyList(), 0.0);
    }

    V startVertex = null;
    List<V> vertexList = new ArrayList<>();
    Set<E> remainingEdges = new HashSet<>(tour);

    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (startVertex == null) {
            startVertex = source;
            vertexList.add(startVertex);
        }

        if (vertexList.contains(source) && !vertexList.contains(target)) {
            vertexList.add(target);
        } else if (vertexList.contains(target) && !vertexList.contains(source)) {
            vertexList.add(source);
        } else {
            throw new IllegalArgumentException("The set of edges does not form a valid tour");
        }

        remainingEdges.remove(edge);

        if (remainingEdges.isEmpty()) {
            V lastVertex = vertexList.get(vertexList.size() - 1);
            if (!graph.containsEdge(lastVertex, startVertex)) {
                throw new IllegalArgumentException("The set of edges does not form a valid cycle");
            }
            break;
        }
    }

    double weight = 0.0;
    for (E edge : tour) {
        weight += graph.getEdgeWeight(edge);
    }

    return new SimpleGraphPath<>(graph, startVertex, vertexList, weight);
}

