private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    try {
        if (descriptor.startsWith("(")) {
            // Method descriptor
            int endIndex = descriptor.indexOf(')');
            if (endIndex == -1) {
                throw new IllegalArgumentException("Invalid method descriptor");
            }
            String argumentTypes = descriptor.substring(1, endIndex);
            int index = 0;
            while (index < argumentTypes.length()) {
                char type = argumentTypes.charAt(index);
                switch (type) {
                    case 'B': // byte
                    case 'C': // char
                    case 'F': // float
                    case 'I': // int
                    case 'S': // short
                    case 'Z': // boolean
                        index++;
                        pop(); // Pop one slot
                        break;
                    case 'D': // double
                    case 'J': // long
                        index++;
                        pop2(); // Pop two slots
                        break;
                    case 'L': // object
                    case '[': // array
                        int semiColonIndex = argumentTypes.indexOf(';', index);
                        if (semiColonIndex == -1) {
                            throw new IllegalArgumentException("Invalid object or array descriptor");
                        }
                        index = semiColonIndex + 1;
                        pop(); // Pop one slot
                        break;
                    default:
                        throw new IllegalArgumentException("Unknown type in descriptor");
                }
            }
        } else {
            // Field descriptor
            switch (descriptor.charAt(0)) {
                case 'B': // byte
                case 'C': // char
                case 'F': // float
                case 'I': // int
                case 'S': // short
                case 'Z': // boolean
                    pop(); // Pop one slot
                    break;
                case 'D': // double
                case 'J': // long
                    pop2(); // Pop two slots
                    break;
                case 'L': // object
                case '[': // array
                    pop(); // Pop one slot
                    break;
                default:
                    throw new IllegalArgumentException("Unknown type in descriptor");
            }
        }
    } catch (StringIndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor format", e);
    }
}

