    if (file == null || !file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("Invalid file provided");
    }

    if (timeRanges == null) {
        throw new IllegalArgumentException("Time ranges list cannot be null");
    }

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot snapshot = parseThreadSnapshot(line);
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (snapshot.getTimestamp() >= timeRange.getStartTime() && snapshot.getTimestamp() <= timeRange.getEndTime()) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    } catch (IOException e) {
        throw new IOException("Error reading from file: " + file.getName(), e);
    }

    return result;
}

